"저장은 VM·시간(1시간) 단위 누적(bill_usage): 켜짐 블록 수, Σ vCPU, Σ 메모리, Σ 디스크, Σ vCPU×CPU%, Σ 메모리×메모리%": "Stored as per-VM·hour (1 hour) accumulations (bill_usage): powered-on block count, Σ vCPU, Σ memory, Σ disk, Σ vCPU×CPU%, Σ memory×memory%",
"꺼짐 블록의 Σ 디스크 → 5분 정산과 같은 결과를 1/12 행 수로 보관(기본 400일)": "Σ disk for powered-off blocks → same result as 5-min billing with 1/12 the rows (retained 400 days by default)",
"· 비용(켜짐 5분 블록마다): (vCPU×vCPU 단가 + 메모리GB×GB 단가 + 디스크GB×GB 단가) × 5/60": "· Cost (per powered-on 5-min block): (vCPU×vCPU unit price + memory GB×GB unit price + disk GB×GB unit price) × 5/60",
"꺼진 블록은 과금하지 않음(요율표 bill_disk_when_off 를 켜면 디스크만 과금)": "Powered-off blocks are not charged (enable rate card bill_disk_when_off to charge disk only)",
"사용률 가중(선택, vCPU·메모리만): 가중치 = 최소 가중치 + (1 − 최소 가중치) × 사용률/100": "Utilization weighting (optional, vCPU·memory only): weight = min weight + (1 − min weight) × utilization/100",
"· 요율 버전: 요율을 바꾸면 적용 시작 시각과 함께 새 버전이 쌓이고, 각 시간 행은 그 시각에 유효한 버전으로 계산(소급 없음)": "· Rate versions: changing a rate adds a new version with its effective start time; each hourly row is calculated with the version valid at that time (not retroactive)",
