"NSX T0 BGP 세션 없음 — NSX 커넥터(Auditor)를 추가하면 Edge ↔ 스위치 BGP 를 표시": "No NSX T0 BGP sessions — add an NSX connector (Auditor) to show Edge ↔ switch BGP",
"NSX T0 BGP 세션이 없습니다 — NSX 커넥터(읽기 전용 Auditor)를 추가하면": "No NSX T0 BGP sessions — add an NSX connector (read-only Auditor) and",
"로 Edge ↔ 물리 스위치 세션을 가져옵니다.": " is used to fetch Edge ↔ physical switch sessions.",
"NSX 커넥터가 있으면 Edge ↔ 물리 스위치 BGP 세션도 함께 표시합니다. 로그는 장비에서": "With an NSX connector, Edge ↔ physical switch BGP sessions are shown too. Send device logs with",
"로 514/udp 에 보내면 '네트워크' 도메인으로 분류됩니다.": "to 514/udp and they are classified into the 'Network' domain.",
"Edge 별 connection_state(PolicyBgpNeighborStatus), 스위치 상태": "per-Edge connection_state (PolicyBgpNeighborStatus), switch state",
"스위치의 BGP 요약에서 Edge 업링크 주소로 찾은 피어. 둘이 다르면 '불일치'. 스위치를 못 찾으면 '미수집'(해당 스위치 커넥터를 추가).": "the peer found by Edge uplink address in the switch BGP summary. Different = 'Mismatch'. Switch not found = 'Not collected' (add that switch connector).",
"스위치 포트 ↔ vmnic 은 스위치 LLDP/CDP 와 ESXi 쪽 LLDP/CDP(QueryNetworkHint, 15분) 를 합쳐서 그립니다. 둘이 가리키는 포트가 다르면 '불일치'. 점검: 가상 스위치 업링크가 한 스위치에만 연결(이중화 없음)·업링크 다운·속도 혼재·포트/NIC 속도 불일치.": "Switch port ↔ vmnic combines switch LLDP/CDP with ESXi-side LLDP/CDP (QueryNetworkHint, 15 min). If they point to different ports: 'Mismatch'. Checks: all virtual-switch uplinks on one switch (no redundancy) · uplink down · mixed speeds · port/NIC speed mismatch.",
"1시간 평균의 최댓값(순간 피크보다 낮게 나옴) — 배치·월말 작업 VM 은 업무 주기를 확인하세요. 신뢰도": "maximum of hourly averages (lower than instantaneous peaks) — check business cycles for batch/month-end VMs. Confidence",
